// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        // owner of c is address(this) (deployer in setUp)
        vm.assume(receiver != address(this));   // receiver distinct from owner/msg.sender
        vm.assume(receiver != address(c));
        amount = bound(amount, 1, 1 ether);

        vm.deal(address(c), amount);
        uint256 balBefore = receiver.balance;

        vm.prank(address(this)); // owner calls
        c.sendTo(receiver, amount);

        // GENERAL RULE: the receiver parameter is paid exactly `amount`.
        assertTrue(receiver.balance == balBefore + amount, "receiver must be paid amount");
    }
}
